SELECT p.id AS position_id, e.id, e.event_type, e.old_value_usdt, e.new_value_usdt, e.market_price_usdt, e.occurred_at, LEFT(e.reason, 500) AS reason FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position w ON w.entry_signal_id = p.signal_id AND w.symbol = p.symbol JOIN crypto_ai.position_management_event e ON e.wallet_position_id = w.id WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, e.occurred_at LIMIT 200